UPDATE skills SET description = 'Putting on a hood, coverall, boots, gloves and mask in the right order so skin, hair and street clothes shed nothing into a cleanroom. A person who has it can gown and de-gown without touching the outside of the garment.',
  how_learned = 'Taught and checked on the first day in a cleanroom job; semiconductor technician programs practice it.', tools = ARRAY['Bunny suits', 'Gowning benches', 'Air showers']
